from __future__ import annotations

import argparse
import json
import shutil
import subprocess
import tempfile
import threading
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path

from cavada_eval.performance import (
    load_performance_plan,
    load_performance_runtime,
    run_performance_campaign,
)
from cavada_eval.protocol import sha256_file

SOURCE_COMMIT = "9fd83112f0fd62e7dd1832cb50eb1c4a3671cbd7"


class _Handler(BaseHTTPRequestHandler):
    def do_POST(self) -> None:  # noqa: N802
        payload = json.loads(self.rfile.read(int(self.headers["Content-Length"])))
        assert payload["model"] == "fixture-model"
        assert payload["stream"] is True
        assert payload["stream_options"] == {"include_usage": True}
        events = (
            {"model": "fixture-model", "choices": [{"delta": {"content": "one "}}]},
            {"model": "fixture-model", "choices": [{"delta": {"content": "two"}}]},
            {"choices": [], "usage": {"prompt_tokens": 8, "completion_tokens": 2}},
        )
        body = b"".join(f"data: {json.dumps(event)}\n\n".encode() for event in events) + b"data: [DONE]\n\n"
        self.send_response(200)
        self.send_header("Content-Type", "text/event-stream")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def log_message(self, _format: str, *_args: object) -> None:
        pass


def _git(source: Path, *args: str) -> str:
    return subprocess.run(  # noqa: S603 -- fixed git subcommands against an explicit local checkout.
        ["git", "-C", str(source), *args],  # noqa: S607 -- git is the documented fixture prerequisite.
        check=True,
        stdout=subprocess.PIPE,
        text=True,
    ).stdout.strip()


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--historical-source", type=Path, required=True)
    parser.add_argument("--output", type=Path, required=True)
    args = parser.parse_args()
    source = args.historical_source.resolve()
    output = args.output.resolve()
    if _git(source, "rev-parse", "HEAD") != SOURCE_COMMIT or _git(source, "status", "--porcelain"):
        raise SystemExit(f"historical source must be a clean checkout of {SOURCE_COMMIT}")
    if output.exists():
        raise SystemExit(f"refusing to overwrite {output}")

    server = ThreadingHTTPServer(("127.0.0.1", 0), _Handler)
    thread = threading.Thread(target=server.serve_forever, daemon=True)
    thread.start()
    try:
        with tempfile.TemporaryDirectory(prefix="cavada-v1-fixture-") as temporary:
            root = Path(temporary)
            workload = root / "workload.jsonl"
            workload.write_text(
                json.dumps({"id": "ctx-8", "context_tokens": 8, "repeat_text": " datum", "repeat_count": 8}) + "\n",
                encoding="utf-8",
            )
            plan = root / "plan.toml"
            plan.write_text(
                f'''plan_version = "1.0.0"
revision = "1.0.0"
name = "historical-v1-golden"
description = "Minimal synthetic compatibility fixture generated by the historical v1 runner."
profile = "llm-serving-v1"
data_classification = "synthetic"
[workload]
id = "historical-v1-golden"
revision = "1.0.0"
path = "workload.jsonl"
sha256 = "{sha256_file(workload)}"
mode = "iso-token"
input_token_tolerance_fraction = 0
[generation]
stream = true
temperature = 0
[execution]
repetitions = 1
warmup_requests = 0
measured_requests = 1
open_loop_duration_seconds = 0
bootstrap_samples = 100
seed = 4345
randomize_cells = false
cooldown_seconds = 0
max_in_flight = 1
[limits]
timeout_seconds = 5
max_requests = 1
max_total_tokens = 10
max_campaign_seconds = 10
max_context_tokens = 8
max_output_tokens = 2
[slo]
ttft_p95_ms = 5000
e2e_p99_ms = 5000
goodput_ttft_ms = 5000
goodput_e2e_ms = 5000
maximum_error_rate = 0
minimum_output_tokens_fraction = 1
[[scenarios]]
id = "closed"
arrival = "closed-loop"
context_tokens = [8]
output_tokens = [2]
concurrency = [1]
''',
                encoding="utf-8",
            )
            runtime = root / "runtime.toml"
            runtime.write_text(
                f'''runtime_version = "1.0.0"
id = "loopback-fixture"
endpoint = "http://127.0.0.1:{server.server_port}/v1"
request_model = "fixture-model"
expected_model = "fixture-model"
model_revision = "{'a' * 40}"
api_key_env = "MISSING_FIXTURE_KEY"
engine = "stdlib-loopback"
engine_revision = "{'b' * 40}"
model_artifact_revision = "{'c' * 64}"
dtype = "synthetic"
quantization = "none"
gpu_count = 1
gpu_model = "synthetic-fixture-device"
tensor_parallel = 1
max_context_tokens = 10
launch_command_sanitized = "python stdlib loopback fixture server"
''',
                encoding="utf-8",
            )
            run = run_performance_campaign(
                load_performance_plan(plan),
                load_performance_runtime(runtime),
                repo_root=source,
                output_root=root / "run",
                signing_key_env="MISSING_FIXTURE_SIGNING_KEY",
            )
            shutil.copytree(run, output)
    finally:
        server.shutdown()
        thread.join()


if __name__ == "__main__":
    main()
